#!/usr/bin/env bash
# Close open issues with no activity for more than two months.
# Run with --apply to make changes; without it, this script only lists matches.
set -euo pipefail

readonly CLOSE_COMMENT='Issue automatically closed. Please create a new one if the issue persists'

apply=false
repo=''

usage() {
  cat <<'EOF'
Usage: scripts/close-stale-issues.sh [--apply] [--repo OWNER/REPO]

Lists open issues inactive for more than two months. Pass --apply to add the
standard closing comment and close each matching issue.
EOF
}

while (($#)); do
  case "$1" in
    --apply)
      apply=true
      ;;
    --repo)
      repo=${2:?--repo requires OWNER/REPO}
      shift
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      usage >&2
      exit 1
      ;;
  esac
  shift
done

command -v gh >/dev/null || {
  echo 'GitHub CLI (gh) is required.' >&2
  exit 1
}

gh auth status >/dev/null

if [[ -z "$repo" ]]; then
  repo=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
fi

cutoff=$(node -e 'const date = new Date(); date.setMonth(date.getMonth() - 2); console.log(date.toISOString().slice(0, 10));')
issues=()
while IFS= read -r issue; do
  [[ -n "$issue" ]] && issues+=("$issue")
done < <(gh issue list --repo "$repo" --state open --search "updated:<$cutoff" --limit 1000 --json number --jq '.[].number')

echo "Repository: $repo"
echo "Closing threshold: no activity since before $cutoff"

if ((${#issues[@]} == 0)); then
  echo 'No matching open issues.'
  exit 0
fi

printf 'Matching issues: %s\n' "${issues[*]}"

if ! "$apply"; then
  echo 'Dry run only. Re-run with --apply to comment on and close these issues.'
  exit 0
fi

for issue in "${issues[@]}"; do
  echo "Closing #$issue"
  gh issue comment "$issue" --repo "$repo" --body "$CLOSE_COMMENT"
  gh issue close "$issue" --repo "$repo"
done
